//! 🔺️ reorder-buffers leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfBuffer;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::reorder_buffers::mutation::{apply, validate, GltfReorderBuffersPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{buffers_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-buffers.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderBuffersOperation { Insert { position: usize, item: GltfBuffer, bytes: Vec<u8> }, Delete { index: usize, removed: GltfBuffer, bytes: Vec<u8> }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderBuffersDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderBuffersPayload, pub operation: GltfReorderBuffersOperation }
async fn operation(payload: &GltfReorderBuffersPayload, base: &GltfSnapshot) -> GltfReorderBuffersOperation { GltfReorderBuffersOperation::Reorder { order: payload.order.clone() } }
async fn touched_paths(payload: &GltfReorderBuffersPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/buffers/{}", index)).chain(payload.order.iter().map(|index| format!("buffers/{}", index))).collect() }
pub async fn validate_diff(diff: &GltfReorderBuffersDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub async fn apply_diff(diff: &GltfReorderBuffersDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfReorderBuffersOperation::Insert { position, item, bytes } => { repair(&mut next.document, GltfTopLevelFamily::Buffers, &Change::Insert(*position))?; next.document.buffers.insert(*position, item.clone()); next.buffers.insert(*position, bytes.clone()); }, GltfReorderBuffersOperation::Delete { index, .. } => { buffers_op(&mut next, GltfTopLevelFamily::Buffers, *index, None, None)?; next.buffers.remove(*index); }, GltfReorderBuffersOperation::Move { index, position } => { buffers_op(&mut next, GltfTopLevelFamily::Buffers, *index, Some(*position), None)?; let bytes = next.buffers.remove(*index); next.buffers.insert(*position, bytes); }, GltfReorderBuffersOperation::Reorder { order } => { buffers_op(&mut next, GltfTopLevelFamily::Buffers, order[0], None, Some(order))?; next.buffers = order.iter().map(|index| next.buffers[*index].clone()).collect(); } } Ok(next) }
pub async fn encode(diff: &GltfReorderBuffersDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub async fn derive(payload: &GltfReorderBuffersPayload, base: &GltfSnapshot) -> Result<GltfReorderBuffersDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderBuffersDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub async fn derive_transitional_gltf_diff(payload: &GltfReorderBuffersPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Buffers, base, &next)) }
